package com.bank.flink.fo;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// A pipelined region: operators connected by streaming exchanges, restarted together.
class Region {
    private static final Logger log = Logger.getLogger(Region.class.getName());

    private final String name;
    private final List<Operator> operators = new ArrayList<>();
    private boolean running = true;

    Region(String name) {
        this.name = name;
    }

    void addOperator(Operator op) { operators.add(op); }

    void restart() {
        running = false;
        log.warning(() -> "Region '" + name + "' RESTARTING (" + operators.size()
                + " operators restored from checkpoint)");
        running = true;
    }

    String getName() { return name; }
    boolean isRunning() { return running; }
}
