package com.bank.flink.fo;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

// The job: multiple regions and the data dependencies between them.
class JobGraph {
    private final Map<String, Region> regions = new HashMap<>();
    // regionName -> set of upstream regions it depends on (data lineage)
    private final Map<String, Set<String>> dependencies = new HashMap<>();

    void addRegion(Region region) {
        regions.put(region.getName(), region);
        dependencies.putIfAbsent(region.getName(), new HashSet<>());
    }

    void addDependency(String region, String upstream) {
        dependencies.computeIfAbsent(region, k -> new HashSet<>()).add(upstream);
    }

    Map<String, Region> getRegions() { return regions; }
    Set<String> upstreamOf(String region) {
        return dependencies.getOrDefault(region, new HashSet<>());
    }
}
