package com.bank.flink.fo;

import java.util.HashSet;
import java.util.Set;

// Full restart: restart EVERY region, no matter where the failure was.
class FullRestartStrategy implements FailoverStrategy {
    @Override
    public Set<String> regionsToRestart(JobGraph job, Operator failed) {
        return new HashSet<>(job.getRegions().keySet()); // everything
    }

    @Override
    public String name() { return "full"; }
}
