package com.bank.flink.fo;

import java.util.HashSet;
import java.util.Set;

// Region failover: restart the failed region plus any region that depends
// on its (now lost) intermediate result. Independent regions keep running.
class RegionFailoverStrategy implements FailoverStrategy {
    @Override
    public Set<String> regionsToRestart(JobGraph job, Operator failed) {
        Set<String> toRestart = new HashSet<>();
        String failedRegion = failed.getRegionName();
        toRestart.add(failedRegion);
        // Any region that consumes the failed region's output must also restart.
        for (String region : job.getRegions().keySet()) {
            if (job.upstreamOf(region).contains(failedRegion)) {
                toRestart.add(region);
            }
        }
        return toRestart;
    }

    @Override
    public String name() { return "region"; }
}
