package com.bank.flink.fo;

import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: independent fraud/interest/reporting regions; a failure in
// interest. Compare full restart vs region failover.
public class FailoverDemo {
    private static final Logger log = Logger.getLogger(FailoverDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new FoLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JobGraph job = buildJob();
        Operator failed = new Operator("InterestCalc", "interest");

        runFailover(buildJob(), new FullRestartStrategy(), failed);
        runFailover(buildJob(), new RegionFailoverStrategy(), failed);
    }

    private static JobGraph buildJob() {
        JobGraph job = new JobGraph();
        Region fraud = new Region("fraud");
        fraud.addOperator(new Operator("FraudSource", "fraud"));
        fraud.addOperator(new Operator("FraudScore", "fraud"));
        Region interest = new Region("interest");
        interest.addOperator(new Operator("InterestSource", "interest"));
        interest.addOperator(new Operator("InterestCalc", "interest"));
        Region reporting = new Region("reporting");
        reporting.addOperator(new Operator("ReportSource", "reporting"));
        reporting.addOperator(new Operator("ReportWriter", "reporting"));
        job.addRegion(fraud);
        job.addRegion(interest);
        job.addRegion(reporting);
        // All three are independent (no cross dependencies).
        return job;
    }

    private static void runFailover(JobGraph job, FailoverStrategy strategy, Operator failed) {
        log.info(() -> "=== Failover strategy: " + strategy.name()
                + " | failure in '" + failed.getRegionName() + "' ===");
        Set<String> toRestart = strategy.regionsToRestart(job, failed);
        for (String regionName : job.getRegions().keySet()) {
            Region region = job.getRegions().get(regionName);
            if (toRestart.contains(regionName)) {
                region.restart();
            } else {
                log.info(() -> "Region '" + regionName + "' KEEPS RUNNING (unaffected)");
            }
        }
        log.info(() -> strategy.name() + " restarted " + toRestart.size()
                + " of " + job.getRegions().size() + " regions");
    }
}

// ─── Would be in FoLogFormatter.java in a real project ───
class FoLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
